"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["54622"],{73546(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_do_fada.fato_elegibilidade_invalido","status":422,"titulo":"O c\xf3digo do fato de elegibilidade do acr\xe9scimo \xe9 inv\xe1lido"},"descricao":{"codigo":"uniplus.selecao.configuracao_do_fada.fato_elegibilidade_invalido","requisitos":[],"oQueAconteceu":["A declara\xe7\xe3o do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso citou, em\\n`fatoElegibilidadeCodigo`, um c\xf3digo de fato em branco ou com mais de 60 caracteres (limite\\nde hoje; os espa\xe7os nas pontas n\xe3o contam). O fato de elegibilidade \xe9 o fato do processo que\\ndecide quem recebe o acr\xe9scimo; a cita\xe7\xe3o \xe9 opcional neste ponto, mas, quando feita, o c\xf3digo\\nprecisa ter de 1 a 60 caracteres.","Esta recusa confere s\xf3 a forma do c\xf3digo. Se o fato \xe9 do processo e se \xe9 do tipo verdadeiro ou\\nfalso s\xe3o confer\xeancias separadas, com outros c\xf3digos de erro.","A recusa vem no campo `fatoElegibilidadeCodigo` e acumula, na mesma resposta, com as demais\\nviola\xe7\xf5es dos valores do fator, em\\n[`fator_invalido`](/erros/uniplus.selecao.configuracao_do_fada.fator_invalido) e\\n[`teto_invalido`](/erros/uniplus.selecao.configuracao_do_fada.teto_invalido).\\nEla vem depois da confer\xeancia da regra e da base legal; se alguma delas falhar, os valores\\nnem chegam a ser conferidos.","Esta mesma confer\xeancia tamb\xe9m roda quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada, na retifica\xe7\xe3o em ato \xfanico. Nesse caso a recusa sai como uma viola\xe7\xe3o \xfanica (sem a lista `errors[]`) e se\\nrefere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["Na declara\xe7\xe3o, informe o c\xf3digo exato do fato do processo que decide quem recebe o acr\xe9scimo,\\ncom 1 a 60 caracteres, ou omita o campo.","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o pedido enviado agora n\xe3o \xe9 a causa: o sistema recusou a\\nconfigura\xe7\xe3o congelada da vers\xe3o publicada, e regravar a configura\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Declara\xe7\xe3o do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao do fada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);